interface.definition:
a!localVariables(
  local!readOnly: true,
  local!jobType: ri!jobType,
  local!jobTypeTransactionCount: if(
    local!readOnly,
    #"SYSTEM_SYSRULES_queryRecordByIdentifier"(
      recordType: #"urn:appian:record-type:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a",
      identifier: ri!jobType[#"urn:appian:record-field:v1:b3b53bd9-776c-40c2-a42b-bd112b0fd293/id"]
    ),
    {}
  ),
  #"SYSTEM_SYSRULES_columnsLayout"(
    columns: {
      #"SYSTEM_SYSRULES_columnLayout"(width: "EXTRA_NARROW"),
      #"SYSTEM_SYSRULES_columnLayout"(
        contents: {
          #"_a-0000e7da-c788-8000-d625-01ef9001ef90_28981"(
            title: "Perspectiva general",
            contents: {
              #"_a-0000e470-9a48-8000-8592-01ef9001ef90_106979"(
                jobType: local!jobType,
                readOnly: local!readOnly,
                batchSize: ri!batchSize,
                ejecutionInterval: ri!ejecutionInterval,
                recordContext: true
              ),
              #"SYSTEM_SYSRULES_ButtonLayout"(
                secondaryButtons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
                  label: "Edit Details",
                  saveInto: a!save(target: local!readOnly, value: false)
                ),
                showWhen: and(#"_a-0000e470-9a48-8000-8592-01ef9001ef90_106893"(), local!readOnly)
              ),
              #"SYSTEM_SYSRULES_ButtonLayout"(
                primaryButtons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
                  label: "Update",
                  saveInto: {
                    a!save(target: local!readOnly, value: true),
                    #"SYSTEM_SYSRULES_startProcess"(
                      processModel: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_107007",
                      processParameters: {
                        jobType: local!jobType,
                        batchSize: ri!batchSize,
                        ejecutionInterval: ri!ejecutionInterval
                      }
                    )
                  },
                  style: "SOLID"
                ),
                secondaryButtons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
                  label: "Cancel",
                  saveInto: a!save(target: local!readOnly, value: true),
                  style: "OUTLINE"
                ),
                showWhen: and(
                  not(local!readOnly),
                  not(contains(#"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6859502", ri!jobType[#"urn:appian:record-field:v1:b3b53bd9-776c-40c2-a42b-bd112b0fd293/modelUuid"]))
                )
              )
            }
          ),
          #"SYSTEM_SYSRULES_cardLayout"(style: "STANDARD", showBorder: false),
          if(
            local!readOnly,
            #"_a-0000e7da-c788-8000-d625-01ef9001ef90_28981"(
              title: "Métricas",
              contents: {
                #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: {
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"_a-0000e470-9a48-8000-8592-01ef9001ef90_107284"(
                          failedCount: local!jobTypeTransactionCount[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/failedCount"],
                          maxRunning: local!jobTypeTransactionCount[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/maxRunning"],
                          runningCount: local!jobTypeTransactionCount[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/runningCount"],
                          label: "Capacidad utilizada",
                          labelPosition: "JUSTIFIED"
                        ),
                        #"SYSTEM_SYSRULES_integerField"(
                          label: "Recuento ejecución",
                          labelPosition: "JUSTIFIED",
                          value: local!jobTypeTransactionCount[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/runningCount"],
                          readOnly: true
                        ),
                        #"SYSTEM_SYSRULES_integerField"(
                          label: "Recuento cola",
                          labelPosition: "JUSTIFIED",
                          value: local!jobTypeTransactionCount[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/queuedCount"],
                          readOnly: true
                        ),
                        #"SYSTEM_SYSRULES_integerField"(
                          label: "Recuento fallido",
                          labelPosition: "JUSTIFIED",
                          value: local!jobTypeTransactionCount[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/failedCount"],
                          readOnly: true
                        ),
                        #"SYSTEM_SYSRULES_integerField"(
                          label: "Recuento cancelado",
                          labelPosition: "JUSTIFIED",
                          value: local!jobTypeTransactionCount[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/cancelledCount"],
                          readOnly: true
                        ),
                        #"SYSTEM_SYSRULES_integerField"(
                          label: "Recuento completo",
                          labelPosition: "JUSTIFIED",
                          value: local!jobTypeTransactionCount[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/completedCount"],
                          readOnly: true
                        )
                      },
                      width: "NARROW_PLUS"
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"_a-0000e470-9a48-8000-8592-01ef9001ef90_106912"(
                          jobTypeId: local!jobTypeTransactionCount[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/id"]
                        )
                      }
                    )
                  }
                )
              }
            ),
            {}
          )
        }
      ),
      #"SYSTEM_SYSRULES_columnLayout"(width: "EXTRA_NARROW")
    }
  )
)
